// 动态指导助手 · 在线版
// 想更新：把下面引号里的版本号改成新版本（比如 'v4.3.4'），保存后刷新酒馆页面。
// 不改就一直用这个版本，不会自己升级。版本号在 GitHub 发布页能看到。
const VERSION = 'v4.8.6';

(async () => {
    const NAME = '动态指导助手';
    const REPO = 'PlayerAlex/sillytavern-dynamic-guide';
    // 几个下载地址同时要，谁先给对就用谁；哪个在你那边连不上也没关系。
    const urls = [
        `https://testingcf.jsdelivr.net/gh/${REPO}@${VERSION}/index.js`,
        `https://fastly.jsdelivr.net/gh/${REPO}@${VERSION}/index.js`,
        `https://cdn.jsdelivr.net/gh/${REPO}@${VERSION}/index.js`,
        `https://gcore.jsdelivr.net/gh/${REPO}@${VERSION}/index.js`,
        `https://raw.githubusercontent.com/${REPO}/${VERSION}/index.js`,
    ];
    const mark = `VERSION = '${VERSION.replace(/^v/, '')}'`;
    const stops = [];
    const download = url => new Promise((resolve, reject) => {
        const controller = new AbortController();
        stops.push(controller);
        const timer = setTimeout(() => controller.abort(), 30000);
        fetch(url, { signal: controller.signal, cache: 'force-cache' })
            .then(response => {
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                return response.text();
            })
            .then(code => {
                // 只认这个版本号的文件，下错了不运行。
                if (!code.includes(mark)) throw new Error('下到的不是这个版本');
                resolve({ url, code });
            })
            .catch(error => reject(new Error(`${new URL(url).host}：${error.name === 'AbortError' ? '超时' : error.message}`)))
            .finally(() => clearTimeout(timer));
    });
    let got;
    try {
        got = await Promise.any(urls.map(download));
    } catch (error) {
        const reasons = (error.errors || []).map(item => item.message).join('\n');
        const text = `${NAME} ${VERSION} 下载失败：几个下载地址都连不上，或者没有这个版本号。可以检查版本号有没有写错，或者换离线版。`;
        console.error(`[${NAME}] ${text}\n${reasons}`);
        try { (window.toastr || window.parent.toastr).error(text, NAME, { timeOut: 0, extendedTimeOut: 0 }); } catch (ignore) { /* 没有提示框就只写控制台 */ }
        return;
    }
    stops.forEach(controller => controller.abort());
    console.info(`[${NAME}] 从 ${new URL(got.url).host} 加载 ${VERSION}`);
    // 只运行一次：脚本自己出错不会再换地址重跑。
    const blobUrl = URL.createObjectURL(new Blob([got.code], { type: 'text/javascript' }));
    try {
        await import(blobUrl);
    } finally {
        URL.revokeObjectURL(blobUrl);
    }
})();
